import { randomUUID } from "node:crypto";
import { ConflictError, NotFoundError, ValidationError } from "../domain/errors";
import { Project, Task, TaskStatus, User } from "../domain/entities";
import {
  ProjectRepository,
  TaskFilter,
  TaskRepository,
  UserRepository,
} from "../domain/repositories";

export interface CreateTaskInput {
  title: string;
  description: string;
  dueDate?: string;
  status?: TaskStatus;
  assigneeId?: string;
}

export class TaskService {
  public constructor(
    private readonly users: UserRepository,
    private readonly projects: ProjectRepository,
    private readonly tasks: TaskRepository,
  ) {}

  public createUser(name: string): User {
    this.requireText(name, "name");
    const user: User = { id: randomUUID(), name: name.trim() };
    this.users.add(user);
    return user;
  }

  public createProject(name: string): Project {
    this.requireText(name, "name");
    const project: Project = { id: randomUUID(), name: name.trim() };
    this.projects.add(project);
    return project;
  }

  public createTask(projectId: string, input: CreateTaskInput): Task {
    this.requireProject(projectId);
    this.requireText(input.title, "title");
    this.requireText(input.description, "description");
    const status = input.status ?? "todo";
    if (!this.isTaskStatus(status)) {
      throw new ValidationError("status must be todo, in progress, or done");
    }
    if (input.assigneeId !== undefined) {
      this.requireUser(input.assigneeId);
    }
    const dueDate = input.dueDate === undefined ? undefined : this.parseDueDate(input.dueDate);
    const task: Task = {
      id: randomUUID(),
      projectId,
      title: input.title.trim(),
      description: input.description.trim(),
      dueDate,
      status,
      assigneeId: input.assigneeId,
    };
    this.tasks.add(task);
    return task;
  }

  public listTasks(projectId: string, filter: TaskFilter = {}): Task[] {
    this.requireProject(projectId);
    if (filter.status !== undefined && !this.isTaskStatus(filter.status)) {
      throw new ValidationError("status must be todo, in progress, or done");
    }
    if (filter.assigneeId !== undefined) {
      this.requireUser(filter.assigneeId);
    }
    return this.tasks.findByProjectId(projectId, filter);
  }

  public markDone(taskId: string, projectId?: string): Task {
    const task = this.tasks.findById(taskId);
    if (task === undefined || (projectId !== undefined && task.projectId !== projectId)) {
      throw new NotFoundError("task not found");
    }
    if (task.status === "done") {
      throw new ConflictError("task is already done");
    }
    const completed: Task = { ...task, status: "done" };
    this.tasks.save(completed);
    return completed;
  }

  private requireProject(id: string): void {
    if (this.projects.findById(id) === undefined) throw new NotFoundError("project not found");
  }

  private requireUser(id: string): void {
    if (this.users.findById(id) === undefined) throw new NotFoundError("assignee user not found");
  }

  private requireText(value: string, field: string): void {
    if (typeof value !== "string" || value.trim() === "") {
      throw new ValidationError(`${field} is required`);
    }
  }

  private parseDueDate(value: string): Date {
    if (typeof value !== "string") throw new ValidationError("dueDate must be an ISO date");
    const date = new Date(value);
    if (Number.isNaN(date.getTime())) throw new ValidationError("dueDate must be an ISO date");
    return date;
  }

  private isTaskStatus(value: string): value is TaskStatus {
    return value === "todo" || value === "in progress" || value === "done";
  }
}

